// Copyright (c) 2026 Roshan. All rights reserved.// Proprietary license — see LICENSE file for details.package com.roshan.persona.brain.skillimport com.roshan.persona.brain.bus.BrainBusimport com.roshan.persona.brain.context.BrainContextimport com.roshan.persona.common.CorrelationIdimport kotlinx.coroutines.CoroutineDispatcher/** * NOUS — Skill dispatchers. * * Skill-friendly access to NOUS's bounded dispatchers. Skills inject this * instead of using `Dispatchers.IO` directly (which would bypass the * bounded parallelism Hilt modules). * * Provided by [com.roshan.persona.di.DispatcherModule] via Hilt. * * @see <a href="docs/spec/module2-spec-review.pdf">§3.3 SkillDispatchers</a> */data class SkillDispatchers(    /** General-purpose I/O dispatcher (file, DB, network). */    val io: CoroutineDispatcher,    /** CPU-bound work dispatcher (default = CPU cores). */    val default: CoroutineDispatcher,    /** LLM inference dispatcher (single-threaded, low priority). */    val llm: CoroutineDispatcher,    /** Computer vision dispatcher (MediaPipe / ML Kit). */    val cv: CoroutineDispatcher,    /** Audio pipeline dispatcher (no double-record). */    val audio: CoroutineDispatcher,)/** * NOUS — Skill context. * * Passed to every [BrainSkill.execute] call. Bundles everything a skill needs: * app context, user context, dispatchers, brain bus, correlation ID, and * the original brain context (for ambient/persona info). */data class SkillContext(    val brainContext: BrainContext,    val dispatchers: SkillDispatchers,    val brainBus: BrainBus,    val credentialVault: CredentialVaultInterface,)/** * NOUS — Credential vault interface (Brain's view). * * Module 7 (Security) provides the real implementation backed by Android * Keystore. Brain only needs this minimal interface. * * @see <a href="docs/spec/module2-spec-review.pdf">§7.4 CredentialVault</a> */interface CredentialVaultInterface {    fun storeCredential(skillId: String, key: String, value: String)    fun getCredential(skillId: String, key: String): String?    fun deleteCredential(skillId: String, key: String)    fun deleteAllForSkill(skillId: String)}